fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            let mut lines: Vec<String> = s.lines()
                .map(|line| {
                    if keepends {
                        format!("{}\n", line) // Append newline if keepends is true
                    } else {
                        line.to_string() // Just return the line
                    }
                })
                .collect();

            // Ensure each inner list is non-empty
            if lines.is_empty() {
                lines.push(String::from("")); // Add a placeholder if empty
            }

            lines
        })
        .collect()
}